package com.syscore.ecosched.config;
import com.syscore.ecosched.entity.User; import com.syscore.ecosched.repository.UserRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class AdminProvisioner { @Bean CommandLineRunner provisionAdmin(UserRepository users,PasswordEncoder encoder,@Value("${ADMIN_EMAIL:}") String email,@Value("${ADMIN_PASSWORD:}") String password){return args->{if(email==null||email.isBlank()||password==null||password.length()<8)return;User u=users.findByEmailIgnoreCase(email.trim()).orElseGet(User::new);u.setEmail(email.trim().toLowerCase());u.setFullName("EcoSched Administrator");u.setPhone("0000000000");u.setAddress("Administration");u.setPasswordHash(encoder.encode(password));u.setRole("ADMIN");users.save(u);};}}
